// englishAPIErrorMessage returns the English message for an API error code, or
// a generic fallback when the code is unknown.
func englishAPIErrorMessage(code string) string {
	if message, ok := apiErrorMessagesEnglish[code]; ok {
		return message
	}
	return apiErrorFallbackEnglish
}

// englishAPIErrorMessageFor prefers an exact translation of the source message,
// then the code-level message, then the generic fallback.
func englishAPIErrorMessageFor(code, source string) string {
	if message, ok := apiErrorMessagesEnglishBySource[source]; ok {
		return message
	}
	return englishAPIErrorMessage(code)
}
